def rle_encode(s: str) -> list:
    """Run-length encode a string into a list of [char, count] pairs."""
    result = []
    for ch in s:
        if result and result[-1][0] == ch:
            result[-1][1] += 1
        else:
            result.append([ch, 1])
    return result
```

