def parse_csv_line(line: str) -> list:
    fields = []
    i = 0
    n = len(line)
    while i <= n:
        field = []
        if i < n and line[i] == '"':
            i += 1
            while True:
                if i >= n:
                    break
                if line[i] == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        field.append('"')
                        i += 2
                    else:
                        i += 1
                        break
                else:
                    field.append(line[i])
                    i += 1
        else:
            while i < n and line[i] != ',':
                field.append(line[i])
                i += 1
        fields.append(''.join(field))
        if i < n and line[i] == ',':
            i += 1
        else:
            break
    return fields
```

